// responseVector is one case generated by testdata/gen_response_vectors.py
// from the reference Python agent: the HTTP response served, whether the
// reference confirmed the call, how many requests it made across its retry
// budget (retry_attempts=2) and the breaker failure count it ended with.
type responseVector struct {
	Kind            string            `json:"kind"`
	Status          int               `json:"status"`
	Body            string            `json:"body"`
	Headers         map[string]string `json:"headers"`
	Confirmed       bool              `json:"confirmed"`
	Requests        int               `json:"requests"`
	BreakerFailures int               `json:"breaker_failures"`
}

func TestResponseSemanticsMatchReferenceVectors(t *testing.T) {
	raw, err := os.ReadFile("testdata/response_vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var vectors []responseVector
	if err := json.Unmarshal(raw, &vectors); err != nil {
		t.Fatal(err)
	}
	if len(vectors) == 0 {
		t.Fatal("no vectors")
	}
	for _, v := range vectors {
		var requests atomic.Int64
		server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			requests.Add(1)
			for k, val := range v.Headers {
				w.Header().Set(k, val)
			}
			w.WriteHeader(v.Status)
			_, _ = io.WriteString(w, v.Body)
		}))
		cfg := DefaultConfig()
		cfg.APIKey = "test-api-key-123"
		cfg.Endpoint = server.URL
		cfg.RetryAttempts = 2
		cfg.BackoffFactor = 0.001
		tr := newTransport(cfg, "install", nil, log.New(io.Discard, "", 0))
		ctx := context.Background()
		var confirmed bool
		switch v.Kind {
		case "events":
			outcome, _ := tr.sendEvents(ctx, []SecurityEvent{testEvent(1, "")})
			confirmed = outcomeConfirms(outcome)
		case "status":
			outcome, _ := tr.sendStatus(ctx, agentStatusPayload{Timestamp: time.Now().UTC(), Status: StatusHealthy})
			confirmed = outcome == outcomeAccepted
		default:
			rules, _ := tr.fetchDynamicRules(ctx)
			confirmed = rules != nil
		}
		server.Close()
		if confirmed != v.Confirmed || int(requests.Load()) != v.Requests || tr.breaker.FailureCount() != v.BreakerFailures {
			t.Errorf("%s %d %q: got confirmed=%v requests=%d breaker=%d, reference confirmed=%v requests=%d breaker=%d",
				v.Kind, v.Status, v.Body, confirmed, requests.Load(), tr.breaker.FailureCount(), v.Confirmed, v.Requests, v.BreakerFailures)
		}
	}
}

func TestWireShapeMatchesReference(t *testing.T) {
	raw, err := os.ReadFile("testdata/wire_shape.json")
	if err != nil {
		t.Fatal(err)
	}
	var shapes map[string]map[string]string
	if err := json.Unmarshal(raw, &shapes); err != nil {
		t.Fatal(err)
	}
	cfg := DefaultConfig()
	cfg.APIKey = "test-api-key-123"
	tr := newTransport(cfg, "install", nil, log.New(io.Discard, "", 0))
	// Events and metrics arrive without metadata or tags, the nil cases.
	body, err := tr.marshalBatch(&eventBatch{
		ProjectID: "p", BatchID: "b", CreatedAt: time.Now().UTC(),
		Events:  []SecurityEvent{{Timestamp: time.Now().UTC(), EventType: "x", IdempotencyKey: "k"}},
		Metrics: []SecurityMetric{{Timestamp: time.Now().UTC(), MetricType: MetricRequestCount}},
	})
	if err != nil {
		t.Fatal(err)
	}
	var batch map[string]any
	if err := json.Unmarshal(body, &batch); err != nil {
		t.Fatal(err)
	}
	status, err := json.Marshal(agentStatusPayload{Timestamp: time.Now().UTC(), Status: StatusHealthy, Errors: []string{}})
	if err != nil {
		t.Fatal(err)
	}
	var statusMap map[string]any
	if err := json.Unmarshal(status, &statusMap); err != nil {
		t.Fatal(err)
	}
	assertShape(t, "batch", shapes["batch"], batch)
	assertShape(t, "event", shapes["event"], batch["events"].([]any)[0].(map[string]any))
	assertShape(t, "metric", shapes["metric"], batch["metrics"].([]any)[0].(map[string]any))
	assertShape(t, "status", shapes["status"], statusMap)

	// An events-only batch still carries "metrics": [].
	body, err = tr.marshalBatch(&eventBatch{ProjectID: "p"})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(string(body), `"events":[]`) || !strings.Contains(string(body), `"metrics":[]`) {
		t.Fatalf("an empty batch must carry both lists: %s", body)
	}
}

// assertShape checks every reference key that is non-null is present with
// the same JSON type, and that no key outside the reference set is emitted.
// Reference keys that are null (optional) may be absent or null.
func assertShape(t *testing.T, name string, want map[string]string, got map[string]any) {
	t.Helper()
	kinds := map[string]string{"str": "string", "list": "[]interface {}", "dict": "map[string]interface {}", "bool": "bool", "int": "float64", "float": "float64"}
	for key, kind := range want {
		value, present := got[key]
		if kind == "NoneType" {
			continue
		}
		if !present {
			t.Errorf("%s: reference key %q missing", name, key)
			continue
		}
		if gotKind := typeName(value); gotKind != kinds[kind] {
			t.Errorf("%s.%s: reference %s, got %s", name, key, kind, gotKind)
		}
	}
	for key := range got {
		if _, ok := want[key]; !ok {
			t.Errorf("%s: key %q is not in the reference shape", name, key)
		}
	}
}

func typeName(v any) string {
	switch v.(type) {
	case string:
		return "string"
	case []any:
		return "[]interface {}"
	case map[string]any:
		return "map[string]interface {}"
	case bool:
		return "bool"
	case float64:
		return "float64"
	}
	return "other"
}

func TestEncrypted413SplitsAndReencryptsEachHalf(t *testing.T) {
	m := newMockIngest(t)
	m.setMaxBody(2200)
	cfg := DefaultConfig()
	cfg.APIKey = "test-api-key-123"
	cfg.Endpoint = m.URL
	cfg.ProjectEncryptionKey = testEncryptionKey()
	cfg.RetryAttempts = 0
	tr := newTransport(cfg, "install", nil, log.New(io.Discard, "", 0))
	encryptor, err := NewPayloadEncryptor(testEncryptionKey())
	if err != nil {
		t.Fatal(err)
	}
	tr.encryptor = encryptor
	pad := strings.Repeat("x", 600)
	events := []SecurityEvent{testEvent(1, pad), testEvent(2, pad), testEvent(3, pad), testEvent(4, pad)}
	outcome, err := tr.sendEvents(context.Background(), events)
	if outcome != outcomeAccepted || err != nil {
		t.Fatalf("an encrypted 413 must split and confirm, got %v %v", outcome, err)
	}
	var oversized, accepted int
	for _, c := range m.callsTo(encryptedPath) {
		if c.Response == http.StatusRequestEntityTooLarge {
			oversized++
		} else {
			accepted++
		}
	}
	if oversized < 1 || accepted < 2 {
		t.Fatalf("expected a 413 then at least two accepted halves, got oversized=%d accepted=%d", oversized, accepted)
	}

	metrics := []SecurityMetric{testMetric(1), testMetric(2)}
	for i := range metrics {
		metrics[i].Tags = map[string]string{"pad": strings.Repeat("y", 1200)}
	}
	m.mu.Lock()
	m.calls = nil
	m.mu.Unlock()
	outcome, err = tr.sendMetrics(context.Background(), metrics)
	if outcome != outcomeAccepted || err != nil {
		t.Fatalf("encrypted metrics 413 must split and confirm, got %v %v", outcome, err)
	}
	if len(m.callsTo(encryptedPath)) < 3 {
		t.Fatalf("metrics must split into re-encrypted halves, calls: %d", len(m.callsTo(encryptedPath)))
	}
}

func TestPermanentGETStatusesDoNotCountAgainstBreaker(t *testing.T) {
	// Covered by the reference vectors (rules 400/404/413/422); this pins
	// the counters the vectors do not assert.
	m := newMockIngest(t)
	cfg := DefaultConfig()
	cfg.APIKey = "test-api-key-123"
	cfg.Endpoint = m.URL
	cfg.RetryAttempts = 1
	cfg.BackoffFactor = 0.001
	tr := newTransport(cfg, "install", nil, log.New(io.Discard, "", 0))
	m.serveRules(http.StatusNotFound, "")
	if _, err := tr.fetchDynamicRules(context.Background()); err == nil {
		t.Fatal("a 404 must exhaust into an error")
	}
	if tr.breaker.FailureCount() != 0 || tr.requestsFailed.Load() != 2 {
		t.Fatalf("404 must retry without breaker failures, got failures=%d failed=%d", tr.breaker.FailureCount(), tr.requestsFailed.Load())
	}
}

func TestRulesLoopNeedsProjectID(t *testing.T) {
	m := newMockIngest(t)
	m.serveRules(http.StatusOK, sampleRulesJSON())
	agent := newTestAgent(t, m, nil)
	agent.cfg.DynamicRuleInterval = time.Millisecond
	agent.tr.limiter = newRateLimiter(1_000_000, time.Hour)
	if err := agent.Start(context.Background()); err != nil {
		t.Fatal(err)
	}
	time.Sleep(100 * time.Millisecond)
	if got := len(m.callsTo(rulesPath)); got != 0 {
		t.Fatalf("no project id must mean no rules polling, got %d GETs", got)
	}
	_ = agent.Stop(context.Background())
}

func TestFailureRateCountsEventsAndMetrics(t *testing.T) {
	agent := newTestAgent(t, nil, nil)
	agent.mu.Lock()
	agent.started = true
	agent.eventsSent = 10
	agent.metricsFailed = 5
	agent.mu.Unlock()
	if s := agent.Status(); s.State != StatusDegraded {
		t.Fatalf("5 failed of 15 attempts is above 10%%, got %q", s.State)
	}
	if !agent.Healthy() {
		t.Fatal("a third failed is under the 50% health threshold")
	}
	agent.mu.Lock()
	agent.metricsFailed = 20
	agent.mu.Unlock()
	if agent.Healthy() {
		t.Fatal("20 failed of 30 attempts is above 50%")
	}
}

func TestStopFlushRespectsBackoffGate(t *testing.T) {
	m := newMockIngest(t)
	m.failNext(1000)
	agent := newTestAgent(t, m, func(c *Config) { c.RetryAttempts = 0 })
	if err := agent.Start(context.Background()); err != nil {
		t.Fatal(err)
	}
	for i := 1; i <= 2; i++ {
		if err := agent.SendEvent(context.Background(), testEvent(i, "")); err != nil {
			t.Fatal(err)
		}
		if err := agent.SendMetric(context.Background(), testMetric(i)); err != nil {
			t.Fatal(err)
		}
	}
	if err := agent.Flush(context.Background()); err == nil {
		t.Fatal("the flush must fail against a 500 server")
	}
	before := m.callCount()
	if err := agent.Stop(context.Background()); err != nil {
		t.Fatalf("Stop under closed gates must not flush: %v", err)
	}
	if m.callCount() != before {
		t.Fatalf("Stop bypassed the backoff gates: %d calls before, %d after", before, m.callCount())
	}
}

func TestCancelledContextIsNotABreakerFailure(t *testing.T) {
	m := newMockIngest(t)
	cfg := DefaultConfig()
	cfg.APIKey = "test-api-key-123"
	cfg.Endpoint = m.URL
	tr := newTransport(cfg, "install", nil, log.New(io.Discard, "", 0))
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	if _, err := tr.sendBatch(ctx, eventsPath, []byte(`{}`)); !errors.Is(err, context.Canceled) {
		t.Fatalf("got %v", err)
	}
	if _, err := tr.fetchDynamicRules(ctx); !errors.Is(err, context.Canceled) {
		t.Fatalf("got %v", err)
	}
	if tr.breaker.FailureCount() != 0 || tr.requestsFailed.Load() != 0 {
		t.Fatalf("a cancelled call must not count: breaker=%d failed=%d", tr.breaker.FailureCount(), tr.requestsFailed.Load())
	}
}

func TestAgentStatsCarriesReferenceKeys(t *testing.T) {
	m := newMockIngest(t)
	agent := newTestAgent(t, m, func(c *Config) { c.RetryAttempts = 0 })
	stats := agent.AgentStats()
	if stats["last_status_push_ok"] != nil {
		t.Fatalf("no push yet must be nil, got %v", stats["last_status_push_ok"])
	}
	if stats["buffer_stats"].(map[string]any)["last_flush_time"] != nil {
		t.Fatal("no flush yet must report a nil last_flush_time")
	}
	if got := stats["transport_stats"].(map[string]any)["session_closed"]; got != true {
		t.Fatalf("an unstarted agent has no open session, got %v", got)
	}
	if err := agent.Start(context.Background()); err != nil {
		t.Fatal(err)
	}
	if err := agent.SendEvent(context.Background(), testEvent(1, "")); err != nil {
		t.Fatal(err)
	}
	if err := agent.Flush(context.Background()); err != nil {
		t.Fatal(err)
	}
	agent.reportStatus(context.Background())
	stats = agent.AgentStats()
	buffer := stats["buffer_stats"].(map[string]any)
	if last, ok := buffer["last_flush_time"].(float64); !ok || last <= 0 {
		t.Fatalf("last_flush_time must be a float epoch, got %v", buffer["last_flush_time"])
	}
	if buffer["auto_flush_running"] != true {
		t.Fatal("a started agent reports auto_flush_running")
	}
	transport := stats["transport_stats"].(map[string]any)
	if transport["bytes_sent"].(int64) <= 0 || transport["failure_count"] != 0 || transport["session_closed"] != false {
		t.Fatalf("transport stats: %v", transport)
	}
	if stats["last_status_push_ok"] != true {
		t.Fatalf("a successful push must report true, got %v", stats["last_status_push_ok"])
	}
	loops := stats["loop_failures"].(map[string]any)
	if loops["flush"] != 0 || loops["status"] != 0 || loops["rules"] != 0 {
		t.Fatalf("loop_failures: %v", loops)
	}
	if transport["circuit_breaker_state"] != "CLOSED" {
		t.Fatalf("breaker spelling: %v", transport["circuit_breaker_state"])
	}

	// A rejected push is a failure for the loop counters and last_status_push_ok.
	m.statusCodeOverride = http.StatusBadRequest
	agent.reportStatus(context.Background())
	stats = agent.AgentStats()
	if stats["last_status_push_ok"] != false || stats["loop_failures"].(map[string]any)["status"] != 1 {
		t.Fatalf("a 400 status push must count as failed: %v", stats)
	}
	_ = agent.Stop(context.Background())
}

func TestFlushLoopFailuresCountOnlyCrashedIterations(t *testing.T) {
	agent := newTestAgent(t, nil, nil, WithHTTPClient(&http.Client{Transport: panicRoundTripper{}}))
	agent.ctx = context.Background()
	if err := agent.SendEvent(context.Background(), testEvent(1, "")); err != nil {
		t.Fatal(err)
	}
	agent.flushTick(0)
	if got := agent.AgentStats()["loop_failures"].(map[string]any)["flush"]; got != 1 {
		t.Fatalf("a crashed flush must count, got %v", got)
	}
	agent.mu.Lock()
	agent.events = nil
	agent.mu.Unlock()
	agent.flushTick(1)
	if got := agent.AgentStats()["loop_failures"].(map[string]any)["flush"]; got != 0 {
		t.Fatalf("a completed iteration must reset the counter, got %v", got)
	}
}

func TestMetricFlushRecoveryResetsStreak(t *testing.T) {
	m := newMockIngest(t)
	m.failNext(1)
	agent := newTestAgent(t, m, func(c *Config) { c.RetryAttempts = 0 })
	if err := agent.SendMetric(context.Background(), testMetric(1)); err != nil {
		t.Fatal(err)
	}
	if err := agent.Flush(context.Background()); err == nil {
		t.Fatal("the first flush must fail")
	}
	agent.mu.Lock()
	agent.metricGate = time.Time{}
	agent.mu.Unlock()
	if err := agent.Flush(context.Background()); err != nil {
		t.Fatalf("the retry must succeed: %v", err)
	}
	if agent.Stats().MetricsSent != 1 {
		t.Fatalf("the metric must be confirmed, got %+v", agent.Stats())
	}
}
